window.kbPageData["views/entry/k-0853e26868da0146"] = {"key":"entry/k-0853e26868da0146","state":{"route":"entry/k-0853e26868da0146"},"node":{"id":"k-0853e26868da0146","mode":"k","title":"推动新型城镇化和区域协调发展","type":"事实与事件","domain":"公共管理","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["regional"],"主类":["事实与事件"],"出处性质":["报告摘登"],"学科":["公共管理","经济"],"时间索引":["年度事件或数据"],"来源主题":["年度政府工作"],"资料类别":["时政"]},"eventTags":[{"year":2026,"title":"政府工作报告","slug":"94fd2d7ef9a6"}],"directorySummary":"不断增强区域发展协调性。优化主体功能区划，引导各地区围绕主体功能定位，更好发\n挥比较优势。扎实推动西部大开发形成新格局、东北全面振兴取得新突破、中部地区加快\n崛起、东部地区加快推进现代化。加强改革攻坚、政策赋能和要素保障，支持经济大省挑大\n梁。支持京津冀、长三角、粤港澳大湾区打造世界级城市群。高标准…","sources":[{"id":"a6a30ccd9a48a5fd","label":"推动新型城镇化和区域协调发展","topic":"年度政府工作","category":"时政","text":"不断增强区域发展协调性。优化主体功能区划，引导各地区围绕主体功能定位，更好发\n挥比较优势。扎实推动西部大开发形成新格局、东北全面振兴取得新突破、中部地区加快\n崛起、东部地区加快推进现代化。加强改革攻坚、政策赋能和要素保障，支持经济大省挑大\n梁。支持京津冀、长三角、粤港澳大湾区打造世界级城市群。高标准高质量推进雄安新区\n建设。持续推进长江经济带发展、黄河流域生态保护和高质量发展。提升成渝地区双城经\n济圈发展能级。推动长江中游城市群等加快发展。加强重点城市群协调联动，健全规划统筹、\n产业协作、利益共享等机制，实施国家产业转移发展提升工程，深化跨行政区合作。加大差\n异化政策支持力度，深入推进兴边富民行动，促进革命老区、民族地区、边疆地区、资源\n枯竭城市等振兴发展。加强主要海湾整体规划，做强做优做大海洋产业。","source":{"doc":"6cbfb01fe723bba64b75","first":39,"last":39,"page":39,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"},{"id":"454b69a203423969","label":"推动新型城镇化和区域协调发展","topic":"年度政府工作","category":"时政","text":"（七）推动新型城镇化和区域协调发展。深入实施区域协调发展战略、区域重大战略、\n主体功能区战略和新型城镇化战略①，构建优势互补、高质量发展的区域经济布局和国土空\n间体系。\n深入推进以人为本的新型城镇化。科学有序推进农业转移人口市民化，因地制宜放宽\n在流入地参加中考报名条件，进一步完善“人地钱”挂钩政策②。优化县域基础设施布局和\n公共资源配置，发展县域特色产业，推动县域经济高质量发展。坚持城市内涵式发展③，优\n化现代化城市体系。高质量推进城市更新，稳步实施城镇老旧小区、城中村等改造。盘活利\n用存量土地和闲置房屋设施。加强城市基础设施生命线安全工程建设，提升高层建筑火灾防\n范和救援能力。建设创新型产业社区、商务社区，推动城市治理智慧化精细化④，建设现代\n化人民城市。","source":{"doc":"6cbfb01fe723bba64b75","first":37,"last":37,"page":37,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"regional","title":"区域协调与城乡融合"}],"units":{"k-0853e26868da0146":[]}};
